"""Writes the kit's generated files from tokens.json: tokens.css, kit.js and index.html, and links every
preview to them. Run it after changing tokens.json or adding a part: python3 build.py
"""
from __future__ import annotations

import html
import json
import re
from pathlib import Path

KIT = Path(__file__).resolve().parent
PREVIEW_HEAD = ('<link rel="stylesheet" href="../../tokens.css"><link rel="stylesheet" href="../bundle.css">'
                '<script src="../../kit.js"></script>')


def main() -> None:
    tokens = json.loads((KIT / "tokens.json").read_text("utf-8"))
    themes = [(theme["id"], theme["name"]) for theme in tokens["color"]["themes"]]
    (KIT / "tokens.css").write_text(tokens_css(tokens, [theme_id for theme_id, _ in themes]), "utf-8")
    (KIT / "kit.js").write_text(kit_js([theme_id for theme_id, _ in themes]), "utf-8")
    cards = [card(preview) for preview in sorted((KIT / "components").glob("*/preview.html"))]
    for preview in (KIT / "components").glob("*/preview.html"):
        link_preview(preview)
    (KIT / "index.html").write_text(index_html(tokens["name"], themes, cards), "utf-8")
    print(f"tokens.css, kit.js and index.html written; {len(cards)} parts")


def tokens_css(tokens: dict, theme_ids: list[str]) -> str:
    """Colour and shadow tokens per theme (the first is the default), then fonts, sizes and type styles."""
    lines = ["/* Generated by build.py from tokens.json. Edit tokens.json, then run python3 build.py. */"]
    for font in tokens["type"].get("fonts", []):
        lines.append(f'@font-face {{ font-family: "{font["family"]}"; src: url("{font["file"]}") format("truetype"); '
                     f'font-weight: {font["weight"]}; font-style: {font["style"]}; }}')
    themed = tokens["color"]["tokens"] + tokens["shadow"]["tokens"]
    for index, theme_id in enumerate(theme_ids):
        selector = f':root, [data-theme="{theme_id}"]' if index == 0 else f'[data-theme="{theme_id}"]'
        values = [f"  --{token['name']}: {value_for(token['value'], theme_id)};" for token in themed]
        lines += [f"{selector} {{", *values, "}"]
    fixed = [f"  --font-{name}: {stack};" for name, stack in tokens["type"]["families"].items()]
    for group in ("spacing", "radius", "size", "scale"):
        fixed += [f"  --{token['name']}: {token['value']};" for token in tokens[group]["tokens"]]
    lines += [":root {", *fixed, "}"]
    for group in tokens["type"]["groups"]:
        for style in group["styles"]:
            lines.append(type_class(style, style.get("family", group["family"])))
    return "\n".join(lines) + "\n"


def value_for(value: object, theme_id: str) -> str:
    return str(value[theme_id]) if isinstance(value, dict) else str(value)


def type_class(style: dict, family: str) -> str:
    rules = [f"font-family: var(--font-{family})", f"font-size: {style['fontSize']}", f"line-height: {style['lineHeight']}",
             f"font-weight: {style['fontWeight']}"]
    if "letterSpacing" in style:
        rules.append(f"letter-spacing: {style['letterSpacing']}")
    return f".{style['name']} {{ {'; '.join(rules)}; }}"


def kit_js(theme_ids: list[str]) -> str:
    return ("/* Generated by build.py. Sets the theme from ?theme=, so index.html can show every part in one theme. */\n"
            "(function () {\n"
            '  var theme = new URLSearchParams(location.search).get("theme");\n'
            f"  if ({json.dumps(theme_ids)}.indexOf(theme) >= 0) document.documentElement.dataset.theme = theme;\n"
            "})();\n")


def card(preview: Path) -> dict:
    """A part's place in index.html, from the @dsCard comment on the preview's first line."""
    first = preview.read_text("utf-8").splitlines()[0]
    attributes = {key: quoted or bare for key, quoted, bare in re.findall(r'(\w+)=(?:"([^"]*)"|([^\s"]+))', first)}
    return {"name": preview.parent.name, "group": attributes.get("group", "Overview"),
            "height": int(attributes.get("height", 300)), "subtitle": attributes.get("subtitle", ""),
            "notes": (preview.parent / "README.md").exists()}


def link_preview(preview: Path) -> None:
    text = preview.read_text("utf-8")
    if PREVIEW_HEAD in text:
        return
    preview.write_text(text.replace("</title>", "</title>" + PREVIEW_HEAD, 1), "utf-8")


def index_html(title: str, themes: list[tuple[str, str]], cards: list[dict]) -> str:
    groups: dict[str, list[dict]] = {}
    for item in sorted(cards, key=lambda c: (c["group"] != "Overview", c["group"], c["name"])):
        groups.setdefault(item["group"], []).append(item)
    sections = []
    for group, items in groups.items():
        sections.append(f"  <h2>{html.escape(group)}</h2>")
        for item in items:
            notes = f' <a href="components/{item["name"]}/README.md">Notes</a>' if item["notes"] else ""
            sections.append(f'  <section><h3>{html.escape(item["name"])}</h3><p>{html.escape(item["subtitle"])}{notes}</p>'
                            f'<iframe data-src="components/{item["name"]}/preview.html" style="height:{item["height"] + 24}px" '
                            f'title="{html.escape(item["name"])}"></iframe></section>')
    buttons = "".join(f'<button data-theme-id="{theme_id}">{html.escape(name)}</button>' for theme_id, name in themes)
    return f"""<!doctype html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>{html.escape(title)}</title>
<style>
  body {{ margin: 0; padding: 32px 16px 64px; background: #101014; color: #f2f2f2; font: 15px/1.5 system-ui, sans-serif; }}
  main {{ max-width: 1040px; margin: 0 auto; }}
  h1 {{ font-size: 30px; font-weight: 600; margin: 0 0 6px; }}
  h2 {{ font-size: 13px; letter-spacing: .12em; text-transform: uppercase; color: #9a9aa6; margin: 40px 0 0; }}
  h3 {{ font-size: 17px; margin: 18px 0 2px; }}
  p {{ margin: 0 0 10px; color: #c4c4cc; }}
  a {{ color: #f2f2f2; }}
  iframe {{ width: 100%; border: 0; border-radius: 10px; display: block; background: #000; }}
  .themes {{ display: flex; gap: 8px; flex-wrap: wrap; margin-top: 14px; }}
  .themes button {{ font: 600 13px system-ui, sans-serif; height: 34px; padding: 0 16px; border-radius: 17px; border: 0;
    cursor: pointer; background: #2a2a33; color: #f2f2f2; }}
  .themes button[aria-pressed="true"] {{ background: #f2f2f2; color: #101014; }}
</style>
</head>
<body>
<main>
  <h1>{html.escape(title)}</h1>
  <p>Every part of the app, in each theme. Sizes are dp: 1px here is 1dp on the TV's 960 × 540 screen.
  Rules and sources are in <a href="README.md">README.md</a>.</p>
  <div class="themes" role="group" aria-label="Theme">{buttons}</div>
{chr(10).join(sections)}
</main>
<script>
  function remembered() {{
    try {{ return localStorage.getItem("rated-arr-kit-theme") || "{themes[0][0]}"; }} catch (e) {{ return "{themes[0][0]}"; }}
  }}
  function show(theme) {{
    try {{ localStorage.setItem("rated-arr-kit-theme", theme); }} catch (e) {{}}
    document.querySelectorAll(".themes button").forEach(function (b) {{ b.setAttribute("aria-pressed", b.dataset.themeId === theme); }});
    document.querySelectorAll("iframe").forEach(function (f) {{ f.src = f.dataset.src + "?theme=" + theme; }});
  }}
  document.querySelectorAll(".themes button").forEach(function (b) {{ b.addEventListener("click", function () {{ show(b.dataset.themeId); }}); }});
  show(remembered());
</script>
</body>
</html>
"""


if __name__ == "__main__":
    main()
